-- Linxea keeps its session in sidecar_session (V142/V159), like the banks before it. The
-- shared table's bank and per-bank error-code CHECKs gain LINXEA, so SQLite rebuilds the
-- table (it cannot alter a CHECK); every existing row and the member index are preserved.
-- Keep the PostgreSQL V159 definition and this one identical in the codes they name.
CREATE TABLE sidecar_session_new (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    bank TEXT NOT NULL,
    member_id INTEGER NOT NULL,
    session_state TEXT NOT NULL,
    encrypted_credentials TEXT,
    unsupported_contracts TEXT,
    last_validated_at TEXT,
    is_active INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0, 1)),
    sync_status TEXT NOT NULL DEFAULT 'IDLE',
    last_sync_started_at TEXT,
    last_sync_completed_at TEXT,
    last_sync_error TEXT,
    last_sync_life_ambiguous INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f000Z', 'now')),
    updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f000Z', 'now')),
    region TEXT,
    CONSTRAINT uq_sidecar_session_bank_member UNIQUE (bank, member_id),
    CONSTRAINT ck_sidecar_session_bank CHECK (bank IN ('AMEX', 'AMUNDI', 'BANQUE_POPULAIRE', 'BNP', 'BOURSE_DIRECT', 'BOURSO', 'CAISSE_EPARGNE', 'CIC', 'CMES', 'CORUM', 'FORTUNEO', 'LINXEA', 'NATIXIS', 'SOFIDY', 'TRADE_REPUBLIC')),
    CONSTRAINT ck_sidecar_session_credentials CHECK ((encrypted_credentials IS NULL) OR (bank IN ('BANQUE_POPULAIRE', 'BOURSO', 'CAISSE_EPARGNE', 'CIC', 'CMES', 'CORUM'))),
    CONSTRAINT ck_sidecar_session_failed_error CHECK (((sync_status = 'FAILED') AND (last_sync_error IS NOT NULL)) OR ((sync_status <> 'FAILED') AND (last_sync_error IS NULL))),
    CONSTRAINT ck_sidecar_session_last_sync_error CHECK ((last_sync_error IS NULL) OR ((bank = 'AMEX') AND (last_sync_error IN ('INVALID_CREDENTIALS', 'INVALID_OTP', 'AUTH_ATTEMPT_EXPIRED', 'SESSION_EXPIRED', 'UPSTREAM_FORMAT_CHANGED', 'INVALID_DATA', 'UPSTREAM_UNAVAILABLE', 'INTERNAL_ERROR'))) OR ((bank = 'AMUNDI') AND (last_sync_error IN ('INVALID_CREDENTIALS', 'CAPTCHA_BLOCKED', 'INVALID_OTP', 'APP_VALIDATION_TIMEOUT', 'AUTH_ATTEMPT_EXPIRED', 'SESSION_EXPIRED', 'PORTFOLIO_INCOMPLETE', 'UPSTREAM_FORMAT_CHANGED', 'INVALID_DATA', 'UPSTREAM_UNAVAILABLE', 'INTERNAL_ERROR'))) OR ((bank = 'BANQUE_POPULAIRE') AND (last_sync_error IN ('SESSION_EXPIRED', 'INVALID_SESSION_STATE', 'INVALID_CREDENTIALS', 'KEYPAD_EXPIRED', 'INVALID_POSITIONS', 'KEYPAD_CHANGED', 'APP_VALIDATION_TIMEOUT', 'AUTH_ATTEMPT_EXPIRED', 'UPSTREAM_FORMAT_CHANGED', 'UPSTREAM_UNAVAILABLE', 'INTERNAL_ERROR'))) OR ((bank = 'BNP') AND (last_sync_error IN ('SESSION_EXPIRED', 'INVALID_SESSION_STATE', 'INVALID_CREDENTIALS', 'KEYPAD_EXPIRED', 'INVALID_POSITIONS', 'KEYPAD_CHANGED', 'MFA_TYPE_UNSUPPORTED', 'INVALID_OTP', 'APP_VALIDATION_TIMEOUT', 'AUTH_ATTEMPT_EXPIRED', 'RATE_LIMITED', 'ACTION_REQUIRED', 'PORTFOLIO_INCOMPLETE', 'UPSTREAM_FORMAT_CHANGED', 'INVALID_DATA', 'UPSTREAM_UNAVAILABLE', 'INTERNAL_ERROR'))) OR ((bank = 'BOURSE_DIRECT') AND (last_sync_error IN ('INVALID_CREDENTIALS', 'INVALID_OTP', 'AUTH_ATTEMPT_EXPIRED', 'SESSION_EXPIRED', 'PORTFOLIO_INCOMPLETE', 'UPSTREAM_FORMAT_CHANGED', 'INVALID_DATA', 'UPSTREAM_UNAVAILABLE', 'INTERNAL_ERROR'))) OR ((bank = 'BOURSO') AND (last_sync_error IN ('INVALID_CREDENTIALS', 'FRAUD_ACK_REQUIRED', 'IDENTITY_SELECTION_UNSUPPORTED', 'MFA_TYPE_UNSUPPORTED', 'APP_VALIDATION_TIMEOUT', 'AUTH_ATTEMPT_EXPIRED', 'SESSION_EXPIRED', 'PORTFOLIO_INCOMPLETE', 'UPSTREAM_FORMAT_CHANGED', 'INVALID_DATA', 'UPSTREAM_UNAVAILABLE', 'INTERNAL_ERROR'))) OR ((bank = 'CAISSE_EPARGNE') AND (last_sync_error IN ('SESSION_EXPIRED', 'INVALID_SESSION_STATE', 'INVALID_CREDENTIALS', 'KEYPAD_EXPIRED', 'INVALID_POSITIONS', 'KEYPAD_CHANGED', 'APP_VALIDATION_TIMEOUT', 'AUTH_ATTEMPT_EXPIRED', 'UPSTREAM_FORMAT_CHANGED', 'UPSTREAM_UNAVAILABLE', 'INTERNAL_ERROR'))) OR ((bank = 'CIC') AND (last_sync_error IN ('INVALID_CREDENTIALS', 'ACTION_REQUIRED', 'MFA_TYPE_UNSUPPORTED', 'INVALID_OTP', 'APP_VALIDATION_TIMEOUT', 'APP_VALIDATION_CANCELLED', 'AUTH_ATTEMPT_EXPIRED', 'SESSION_EXPIRED', 'PORTFOLIO_INCOMPLETE', 'UPSTREAM_FORMAT_CHANGED', 'INVALID_DATA', 'UPSTREAM_UNAVAILABLE', 'INTERNAL_ERROR'))) OR ((bank = 'CMES') AND (last_sync_error IN ('INVALID_CREDENTIALS', 'ACTION_REQUIRED', 'MFA_TYPE_UNSUPPORTED', 'INVALID_OTP', 'APP_VALIDATION_TIMEOUT', 'APP_VALIDATION_CANCELLED', 'AUTH_ATTEMPT_EXPIRED', 'SESSION_EXPIRED', 'PORTFOLIO_INCOMPLETE', 'UPSTREAM_FORMAT_CHANGED', 'INVALID_DATA', 'UPSTREAM_UNAVAILABLE', 'INTERNAL_ERROR'))) OR ((bank = 'CORUM') AND (last_sync_error IN ('INVALID_CREDENTIALS', 'SESSION_EXPIRED', 'MULTIPLE_CONTRACTS', 'PORTFOLIO_INCOMPLETE', 'UPSTREAM_FORMAT_CHANGED', 'INVALID_DATA', 'UPSTREAM_UNAVAILABLE', 'INTERNAL_ERROR'))) OR ((bank = 'FORTUNEO') AND (last_sync_error IN ('INVALID_CREDENTIALS', 'INVALID_OTP', 'AUTH_ATTEMPT_EXPIRED', 'SESSION_EXPIRED', 'INVESTOR_PROFILE_REQUIRED', 'PORTFOLIO_INCOMPLETE', 'UPSTREAM_FORMAT_CHANGED', 'INVALID_DATA', 'UPSTREAM_UNAVAILABLE', 'INTERNAL_ERROR'))) OR ((bank = 'LINXEA') AND (last_sync_error IN ('INVALID_CREDENTIALS', 'INVALID_OTP', 'AUTH_ATTEMPT_EXPIRED', 'SESSION_EXPIRED', 'PORTFOLIO_INCOMPLETE', 'UPSTREAM_FORMAT_CHANGED', 'INVALID_DATA', 'UPSTREAM_UNAVAILABLE', 'INTERNAL_ERROR'))) OR ((bank = 'NATIXIS') AND (last_sync_error IN ('INVALID_CREDENTIALS', 'MFA_TYPE_UNSUPPORTED', 'INVALID_OTP', 'RATE_LIMITED', 'AUTH_ATTEMPT_EXPIRED', 'SESSION_EXPIRED', 'PORTFOLIO_INCOMPLETE', 'UPSTREAM_FORMAT_CHANGED', 'INVALID_DATA', 'UPSTREAM_UNAVAILABLE', 'INTERNAL_ERROR'))) OR ((bank = 'SOFIDY') AND (last_sync_error IN ('INVALID_CREDENTIALS', 'MFA_INVALID', 'FIRST_VISIT_PENDING', 'EMAIL_UNREACHABLE', 'ACCOUNT_INACTIVE', 'RATE_LIMITED', 'AUTH_ATTEMPT_EXPIRED', 'SESSION_EXPIRED', 'PORTFOLIO_INCOMPLETE', 'UPSTREAM_FORMAT_CHANGED', 'INVALID_DATA', 'UPSTREAM_UNAVAILABLE', 'INTERNAL_ERROR'))) OR ((bank = 'TRADE_REPUBLIC') AND (last_sync_error IN ('INVALID_CREDENTIALS', 'INVALID_OTP', 'APP_VALIDATION_TIMEOUT', 'APP_VALIDATION_CANCELLED', 'AUTH_ATTEMPT_EXPIRED', 'SESSION_EXPIRED', 'INVALID_SESSION_STATE', 'RATE_LIMITED', 'UPSTREAM_FORMAT_CHANGED', 'INVALID_DATA', 'UPSTREAM_UNAVAILABLE', 'INTERNAL_ERROR')))),
    CONSTRAINT ck_sidecar_session_life_ambiguous CHECK ((last_sync_life_ambiguous >= 0) AND ((bank = 'CORUM') OR (last_sync_life_ambiguous = 0))),
    CONSTRAINT ck_sidecar_session_region CHECK (((bank = 'BANQUE_POPULAIRE') AND (region IS NOT NULL) AND (region IN ('ALSACE_LORRAINE_CHAMPAGNE', 'AQUITAINE_CENTRE_ATLANTIQUE', 'AUVERGNE_RHONE_ALPES', 'BOURGOGNE_FRANCHE_COMTE', 'BRED', 'GRAND_OUEST', 'MEDITERRANEE', 'NORD', 'OCCITANE', 'RIVES_DE_PARIS', 'SUD', 'VAL_DE_FRANCE'))) OR ((bank <> 'BANQUE_POPULAIRE') AND (region IS NULL))),
    CONSTRAINT ck_sidecar_session_sync_status CHECK (sync_status IN ('IDLE', 'QUEUED', 'RUNNING', 'SUCCESS', 'FAILED')),
    CONSTRAINT ck_sidecar_session_unsupported_contracts CHECK ((unsupported_contracts IS NULL) OR (bank IN ('BANQUE_POPULAIRE', 'CAISSE_EPARGNE'))),
    CONSTRAINT fk_sidecar_session_member FOREIGN KEY (member_id) REFERENCES family_member(id) ON DELETE CASCADE
);

INSERT INTO sidecar_session_new (id, bank, member_id, session_state, encrypted_credentials, unsupported_contracts, last_validated_at, is_active, sync_status, last_sync_started_at, last_sync_completed_at, last_sync_error, last_sync_life_ambiguous, created_at, updated_at, region)
SELECT id, bank, member_id, session_state, encrypted_credentials, unsupported_contracts, last_validated_at, is_active, sync_status, last_sync_started_at, last_sync_completed_at, last_sync_error, last_sync_life_ambiguous, created_at, updated_at, region FROM sidecar_session;

DROP TABLE sidecar_session;
ALTER TABLE sidecar_session_new RENAME TO sidecar_session;

CREATE INDEX ix_sidecar_session_member ON sidecar_session (member_id);
